// Only local disposable schema: compare the exact view contract before/after twice.
const {execFileSync}=require('node:child_process'),{readFileSync}=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const database=process.argv[2],directory=process.argv[3];assert.match(database??'',/^creator_[a-z0-9_]+$/);assert.match(path.basename(directory??''),/^alzhen-planned-routes-[a-f0-9]+$/);
function query(sql){return execFileSync('C:/Program Files/PostgreSQL/18/bin/psql.exe',['-X','-w','-h','127.0.0.1','-p','55443','-U','fixture','-d',database,'-qAt','-v','ON_ERROR_STOP=1','-f','-'],{input:sql,encoding:'utf8',env:{...process.env,PGCLIENTENCODING:'UTF8'},windowsHide:true}).trim();}
assert.equal(path.normalize(query('SHOW data_directory')).toLowerCase(),path.normalize(directory).toLowerCase());
const original=readFileSync('backend/migrations/2026_10_29_proposed_operations_pagination.sql','utf8');
const a=original.indexOf('CREATE VIEW'),b=original.indexOf('REVOKE ALL ON',a);assert.ok(a>0&&b>a);query(original.slice(a,b).replace('CREATE VIEW','CREATE OR REPLACE VIEW'));
const metadata=()=>JSON.parse(query("SELECT json_build_object('definition',pg_get_viewdef('v_operations_report_page'::regclass,true),'columns',(SELECT json_agg(json_build_array(attname,atttypid,atttypmod) ORDER BY attnum) FROM pg_attribute WHERE attrelid='v_operations_report_page'::regclass AND attnum>0),'acl',(SELECT relacl::text FROM pg_class WHERE oid='v_operations_report_page'::regclass))"));
const before=metadata(),proposal=readFileSync('backend/migrations/2026_11_06_proposed_operations_creator_attribution.sql','utf8');query(proposal);const after=metadata();assert.deepEqual(after.columns,before.columns);assert.equal(after.acl,before.acl);assert.equal(after.definition,before.definition.replace('COALESCE(offloads.reported_by, offloads.created_by, offloads.submitted_by)','COALESCE(offloads.created_by, offloads.submitted_by)'));query(proposal);assert.deepEqual(metadata(),after);console.log(JSON.stringify({disposable:true,columns:after.columns.length,onlyCreatorProjectionChanged:true,aclPreserved:true,idempotent:true}));
